{
  "pairs": {
    "conflict_54894c18062076dddcf6be69": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 specifies Section 232 tariffs on Korean automotive products (valued at $44.7B) and mentions potential future Section 232 rates for specific items like unmanned aircraft systems. Claim 2 states a general 25% Section 232 rate applies to auto parts from countries without trade agreements, noting Korea has an agreement (KORUS). The claims address different origins (Korea vs. non-agreement countries) and specific product scopes within the automotive sector.",
      "verification_question": "Does the 25% Section 232 rate for 'certain auto parts' from countries without trade agreements explicitly exclude Korean products covered by KORUS FTA carveouts, or does it apply to specific uncarved-out Korean components?"
    },
    "conflict_d446725c77e588638b0ca532": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 states there is a '10% universal tariff' on most goods and that PCBs are subject to this minimum. Claim 2 clarifies there are no *specific* tariffs targeting PCB imports exclusively, but they still face the universal rate. These statements are complementary: one defines the baseline (universal) and the other clarifies the absence of a product-specific surcharge.",
      "verification_question": "None required; the statements describe a general rule and its application to a specific category without contradiction."
    },
    "conflict_c3e38f5cd14cd4627342821f": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 states there are no *specific* U.S. tariffs on PCB imports (implying a lack of product-specific surcharge beyond general rates). Claim 2 lists specific high tariff rates (e.g., 55%) for 'Flexible PCBs' under the program 'Updated U.S. Import Tariffs on Chinese PCBs'. The claims differ in scope: one refers to a general absence of specific tariffs, while the other details specific punitive tariffs targeting Chinese-origin products.",
      "verification_question": "Does the 'no specific tariff' claim refer to non-Chinese origins or exclude the specific Section 301/IEEPA surcharges listed for Chinese PCBs in the second source?"
    },
    "conflict_246faa06f735953bf785c839": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 describes a total effective tariff of ~35% for Chinese flex PCBs, composed of a 25% Section 301 tariff and a 10% IEEPA global tariff. Claim 2 lists a flat 55% tariff for 'Flexible PCBs' under a program titled 'Updated U.S. Import Tariffs on Chinese PCBs'. The rates (35% vs 55%) and component structures differ, suggesting either different policy stages, calculation methods, or distinct product classifications within the same broad category.",
      "verification_question": "Is the 55% rate in Claim 2 a cumulative total including additional penalties or surcharges not present in the 35% calculation of Claim 1, or do they represent different effective dates or product definitions?"
    },
    "conflict_effe07ae1739c8142d8f67e1": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 states the Section 301 tariff is 25% for all flex/non-FR4 PCBs, with an additional 10% IEEPA tariff, totaling ~35%. Claim 2 lists a single 55% rate for 'Flexible PCBs' under a specific Chinese tariff program. The discrepancy lies in the total rate (35% vs 55%) and whether the 55% figure represents a combined duty stack or a distinct surcharge not accounted for in the first claim's breakdown.",
      "verification_question": "Does the 55% rate cited in Claim 2 include additional penalties, anti-dumping duties, or other surcharges beyond the Section 301 and IEEPA tariffs described in Claim 1?"
    }
  }
}
